/// Returns true if `n` is even.
pub fn is_even(n: u32) -> bool {
    n % 2 == 0
}

/// Executable version: returns true if `n` is even.
pub fn is_even_exec(n: u32) -> bool {
    is_even(n)
}

/// Returns true if the array contains at least one even number.
/// Returns false on an empty array.
pub fn is_product_even(arr: &Vec<u32>) -> bool {
    // Iterate through the array and check if any element is even.
    arr.iter().any(|&x| is_even_exec(x))
}

